// app/users/[id]/page.tsx
// View User Page — styled to match View Area Page
"use client";

import { useState, useEffect } from "react";
import { useParams } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  ArrowLeft,
  Pencil,
  UserCircle,
  Calendar,
  Mail,
  ShieldCheck,
  Loader2,
} from "lucide-react";
import { getUserById, type User } from "@/lib/api/user";
import { useToast } from "@/hooks/use-toast";
import { useUser } from "@/context/UserContext";

export default function ViewUserPage() {
  const params = useParams();
  const { toast } = useToast();
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    if (params.id) {
      fetchUserDetails();
    }
  }, [params.id]);
  const { user: currentUser } = useUser();
  const fetchUserDetails = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await getUserById(params.id as string);
      if (response.success && response.user) {
        setUser(response.user);
      } else {
        setError(response.error || "Failed to fetch user details");
        toast({
          title: "Error",
          description: response.error || "Failed to fetch user details",
          variant: "destructive",
        });
      }
    } catch {
      setError("Failed to fetch user details");
      toast({
        title: "Error",
        description: "Failed to fetch user details",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };


  // Loading State
  if (loading) {
    return (
      <div className="flex flex-1 items-center justify-center p-4">
        <div className="text-center">
          <Loader2 className="mx-auto mb-4 h-12 w-12 animate-spin text-[#8B0000]" />
          <p className="text-lg font-medium text-gray-400">
            Loading user details...
          </p>
        </div>
      </div>
    );
  }

  // Error State or User Not Found
  if (error || !user) {
    return (
      <div className="flex flex-1 items-center justify-center p-4">
        <div className="text-center">
          <UserCircle className="mx-auto mb-4 h-12 w-12 text-gray-600" />
          <h1 className="mb-2 text-xl font-bold text-white">User Not Found</h1>
          <p className="mb-4 text-gray-400">
            {error || "The requested user does not exist."}
          </p>
          <Link href="/user">
            <Button className="bg-[#8B0000] text-white hover:bg-[#6B0000]">
              Back to Users
            </Button>
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-4xl">
        {/* Back Button */}
        <Link
          href="/users"
          className="mb-6 inline-flex items-center gap-2 text-gray-400 hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Users
        </Link>

        {/* Header */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <div className="mb-2 flex items-center gap-3">
              <h1 className="text-2xl font-bold text-white md:text-3xl">
                {user.name}
              </h1>
              <Badge
  className={
    user.isActive
      ? "bg-green-600/20 text-green-400"
      : "bg-red-600/20 text-red-400"
  }
>
  {user.isActive ? "Active" : "Inactive"}
</Badge>
            </div>

            <div className="mt-1 flex items-center space-x-2">
              <p className="mt-1 font-mono text-sm text-gray-400">
                {user.email}
              </p>
              <p className="rounded-md bg-yellow-400 px-2 text-sm font-medium text-black">
                {user.role}
              </p>
            </div>
          </div>
            {currentUser.role=="ADMIN"?(
             <Link href={`/users/${user.id}/edit`}>
              <Button className="gap-2 bg-[#8B0000] text-white hover:bg-[#6B0000]">
                <Pencil className="h-4 w-4" />
                Edit User
              </Button>
            </Link> 
            ) : null }
         
        </div>

        {/* Details Grid */}
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <Card className="border-[#333] bg-[#222]">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-sm font-medium text-gray-400">
                <Mail className="h-4 w-4" />
                Email
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="truncate text-lg font-semibold text-white">
                {user.email}
              </p>
            </CardContent>
          </Card>

          <Card className="border-[#333] bg-[#222]">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-sm font-medium text-gray-400">
                <ShieldCheck className="h-4 w-4" />
                Role
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-lg font-semibold text-white">{user.role}</p>
            </CardContent>
          </Card>

          <Card className="border-[#333] bg-[#222]">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-sm font-medium text-gray-400">
                <UserCircle className="h-4 w-4" />
                Status
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-lg font-semibold text-white">
                {user.isActive ? "Active" : "Inactive"}
              </p>
            </CardContent>
          </Card>

          <Card className="border-[#333] bg-[#222]">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-sm font-medium text-gray-400">
                <Calendar className="h-4 w-4" />
                Created
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-lg font-semibold text-white">
                {formatDate(user.createdAt)}
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Account Summary */}
        <Card className="mt-6 border-[#333] bg-[#222]">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-white">
              <UserCircle className="h-5 w-5" />
              Account Details
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              <div className="flex items-center justify-between rounded-lg border border-[#333] bg-[#1a1a1a] p-3">
                <div>
                  <p className="font-medium text-white">Full Name</p>
                  <p className="text-sm text-gray-400">{user.name}</p>
                </div>
              </div>

              <div className="flex items-center justify-between rounded-lg border border-[#333] bg-[#1a1a1a] p-3">
                <div>
                  <p className="font-medium text-white">Email Address</p>
                  <p className="text-sm text-gray-400">{user.email}</p>
                </div>
              </div>

              <div className="flex items-center justify-between rounded-lg border border-[#333] bg-[#1a1a1a] p-3">
                <div>
                  <p className="font-medium text-white">Access Role</p>
                  <p className="text-sm text-gray-400">{user.role}</p>
                </div>
                <Badge className="bg-yellow-400 px-2 font-medium text-black">
                  {user.role}
                </Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
